const videoUrl = $input.item.json.video_url;
const videoFile = $input.item.binary?.data;

if (!videoUrl && !videoFile) {
  throw new Error('No video URL or file provided');
}

return {
  json: {
    analysis_id: `video_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    timestamp: new Date().toISOString(),
    video_url: videoUrl,
    analysis_types: ['content_moderation', 'scene_detection', 'object_detection', 'text_extraction', 'audio_transcription', 'sentiment_analysis']
  },
  binary: videoFile ? { data: videoFile } : undefined
};

