parameters.functionCode:
const items = $input.all();
const baseData = items.find(item => item.json.analysis_id)?.json;

// Extract transcription
const transcription = items.find(item => item.json.text && item.json.duration);
const transcript = transcription?.json.text || '';
const audioDuration = transcription?.json.duration || 0;

// Extract Google Video AI results
const googleVideo = items.find(item => item.json.annotation_results);
const videoAnnotations = googleVideo?.json.annotation_results?.[0] || {};

const sceneLabels = (videoAnnotations.segment_label_annotations || []).map(label => ({
  description: label.entity?.description,
  confidence: label.segments?.[0]?.confidence,
  category: label.category_entities?.[0]?.description
}));

const explicitContent = (videoAnnotations.explicit_annotation?.frames || []).map(frame => ({
  time_offset: frame.time_offset,
  pornography_likelihood: frame.pornography_likelihood,
  violence_likelihood: frame.violence_likelihood,
  racy_likelihood: frame.racy_likelihood
}));

const shotChanges = (videoAnnotations.shot_annotations || []).length;
const detectedText = (videoAnnotations.text_annotations || []).map(text => text.text).join(' ');

const trackedObjects = (videoAnnotations.object_annotations || []).map(obj => ({
  description: obj.entity?.description,
  confidence: obj.confidence,
  frames_tracked: obj.frames?.length || 0
}));

// Extract content moderation
const moderationResult = items.find(item => {
  try {
    const content = item.json.choices?.[0]?.message?.content;
    if (content) {
      const parsed = JSON.parse(content);
      return parsed.moderation_score !== undefined;
    }
  } catch (e) {}
  return false;
});
const moderation = moderationResult ? JSON.parse(moderationResult.json.choices[0].message.content) : null;

// Calculate overall safety score
const explicitFrames = explicitContent.filter(f => 
  ['VERY_LIKELY', 'LIKELY'].includes(f.pornography_likelihood) ||
  ['VERY_LIKELY', 'LIKELY'].includes(f.violence_likelihood)
).length;

const googleSafetyScore = explicitFrames > 0 ? Math.max(0, 100 - (explicitFrames * 10)) : 100;
const combinedSafetyScore = moderation?.moderation_score && googleSafetyScore ? 
  Math.round((moderation.moderation_score * 0.6 + googleSafetyScore * 0.4)) : 
  (moderation?.moderation_score || googleSafetyScore);

// Generate content insights
const insights = [
  `Video duration: ${audioDuration.toFixed(1)} seconds`,
  `Detected ${shotChanges} scene changes`,
  `Identified ${sceneLabels.length} scene labels`,
  `Tracked ${trackedObjects.length} objects`,
  `Transcription word count: ${transcript.split(/\s+/).length}`,
  detectedText ? `Detected on-screen text: ${detectedText.substring(0, 100)}...` : 'No text detected in video'
];

const result = {
  analysis_id: baseData?.analysis_id,
  timestamp: baseData?.timestamp,
  video_info: {
    url: baseData?.video_url,
    duration: audioDuration,
    shot_changes: shotChanges
  },
  transcription: {
    text: transcript,
    word_count: transcript.split(/\s+/).length,
    language: transcription?.json.language || 'en'
  },
  visual_analysis: {
    scene_labels: sceneLabels.slice(0, 20),
    tracked_objects: trackedObjects.slice(0, 20),
    detected_text: detectedText,
    explicit_content_frames: explicitContent.length,
    flagged_frames: explicitFrames
  },
  content_moderation: {
    combined_safety_score: combinedSafetyScore,
    gpt4_moderation_score: moderation?.moderation_score || null,
    google_safety_score: googleSafetyScore,
    content_rating: moderation?.content_rating || 'Unknown',
    brand_safe: moderation?.brand_safe !== false && combinedSafetyScore >= 80,
    violations: moderation?.violations || [],
    explicit_frames_detected: explicitFrames,
    recommendation: combinedSafetyScore >= 90 ? 'APPROVED' :
                      combinedSafetyScore >= 70 ? 'REVIEW RECOMMENDED' :
                      'FLAGGED - MANUAL REVIEW REQUIRED'
  },
  insights: insights,
  recommendations: moderation?.recommendations || [],
  metadata: {
    analysis_providers: ['whisper', 'google_video_ai', 'gpt4'],
    processing_time_ms: Date.now() - new Date(baseData?.timestamp).getTime()
  }
};

return { json: result };
